-- +goose Up
-- Повторяющиеся структурированные списки (иконка+заголовок+описание,
-- бейдж+описание), в отличие от page_content — есть собственная форма,
-- поэтому типизированные сущности, а не generic-блоки.
CREATE TABLE features (
    id          BIGSERIAL PRIMARY KEY,
    page        TEXT NOT NULL,
    icon        TEXT NOT NULL,
    title       TEXT NOT NULL,
    description TEXT NOT NULL,
    sort_order  INTEGER NOT NULL DEFAULT 0,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_features_page ON features(page);

CREATE TABLE about_items (
    id          BIGSERIAL PRIMARY KEY,
    badge       TEXT NOT NULL,
    description TEXT NOT NULL,
    sort_order  INTEGER NOT NULL DEFAULT 0,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

INSERT INTO features (page, icon, title, description, sort_order) VALUES
    ('home', 'two-formats', 'два формата обучения', 'Обучение в группе по расписанию или свободное посещение — выбирайте формат, который подходит именно вам.', 1),
    ('home', 'people-group', 'комфортное обучение', 'Небольшие группы из 5–7 человек позволяют преподавателю уделить внимание каждому ученику.', 2),
    ('home', 'map-pin', 'центр москвы', 'Школа находится в центре Москвы, в пешей доступности от станций метро Арбатская, Смоленская, Баррикадная и Краснопресненская.', 3),
    ('home', 'flex-start', 'гибкий старт', 'Не нужно ждать набора новой группы — начните обучение, когда будете готовы.', 4),
    ('home', 'eighty-twenty', 'максимум практики', 'Большую часть обучения занимает работа с живыми цветами. Только 20% курса — теория.', 5),
    ('home', 'levels', 'для любого уровня', 'Обучаем как новичков, так и практикующих флористов.', 6),
    ('masterclasses', 'calendar-check', 'свободный график', 'Все мастер-классы проходят по системе свободного посещения. После покупки вы самостоятельно выбираете удобные дату и время. Записаться можно минимум за один день через сайт, в мессенджерах или по телефону.', 1),
    ('masterclasses', 'people-trio', 'для одного, двоих или компании', 'Мы проводим индивидуальные мастер-классы, занятия для двоих и групповые мастер-классы. Вы можете прийти самостоятельно, устроить творческое свидание, отметить день рождения, провести корпоратив или любое другое мероприятие в атмосфере живых цветов.', 2),
    ('masterclasses', 'mc-location', 'в школе или с выездом', 'Мастер-классы проходят в школе флористики ФлоВей, а также в выездном формате. При необходимости преподаватель приедет на вашу площадку со всеми необходимыми материалами и проведёт мастер-класс для любого количества участников.', 3),
    ('masterclasses', 'checklist', 'индивидуальная программа', 'На сайте представлены самые популярные мастер-классы, но ими выбор не ограничивается. Если вы хотите освоить определённую технику, создать конкретный букет или композицию либо провести занятие по собственной программе, мы разработаем мастер-класс специально под ваш запрос.', 4),
    ('masterclasses', 'gift', 'подарочный сертификат', 'Любой мастер-класс можно оформить в виде подарочного сертификата. Вы можете выбрать сертификат на конкретное занятие или универсальный сертификат, чтобы получатель самостоятельно выбрал мастер-класс и удобную дату посещения.', 5),
    ('masterclasses', 'tulips', 'живые цветы и максимум практики', 'Все мастер-классы проходят исключительно на живых цветах. Большую часть занятия занимает практика, а преподаватель сопровождает вас на каждом этапе, помогая освоить технику и получить удовольствие от работы с материалом.', 6);

INSERT INTO about_items (badge, description, sort_order) VALUES
    ('есть свободный формат', 'Формат свободного посещения позволяет начать обучение без ожидания набора группы. Вы сами выбираете удобные даты и время занятий. Каждое занятие начинается с индивидуального объяснения новой темы, после чего основное время посвящено практике под постоянным сопровождением преподавателя.', 1),
    ('есть групповой формат', 'Мы проводим обучение в небольших группах. Ближайшие даты набора можно посмотреть в календаре событий. При раннем бронировании курса действует скидка 10%.', 2),
    ('маленькие группы до 7 человек', 'Мы принципиально не работаем с большими группами. На групповых занятиях обучается до 5–7 человек, а в формате свободного посещения преподаватель одновременно сопровождает не более 5–7 учеников. Такой подход позволяет уделить внимание каждому, ответить на вопросы и помочь закрепить материал на практике.', 3),
    ('только живые цветы', 'Мы убеждены, что работать со спиральной техникой важно сразу на живых цветах. Каждый стебель отличается толщиной, гибкостью, формой и особенностями строения, поэтому именно живой материал учит чувствовать правильное положение цветов в руке и понимать, как формируется спираль. Спиральная техника — это не только положение стеблей, но и умение работать с живым материалом. Поэтому её невозможно полноценно освоить на материале, который не передаёт естественные особенности растений. Чем раньше появляется этот навык, тем увереннее флорист чувствует себя в дальнейшей работе с цветами.', 4),
    ('работаем с 2013 года', 'Школа ФлоВей работает с 2013 года. За это время мы обучили флористике сотни учеников — от новичков до тех, кто решил связать с цветами свою профессию.', 5);

